INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 8, 'theory', 'Quiz: input and output, formatting, and buffering');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 0, 'What does sscanf return?', '["The number of characters read", "Always 0 on success", "A pointer to the rest of the string", "The number of fields successfully parsed and stored (or EOF)"]', 3, 'The result of sscanf shows how many fields were actually parsed: if it returns fewer than expected, some of the values stay unchanged and must not be used.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 1, 'What happens with snprintf(buf, 8, "%d", 123456789)?', '["buf gets 7 characters and a zero, and 9 is returned — the length of the full result", "Nine digits are written and memory beyond the buffer is corrupted", "−1 is returned and buf is unchanged", "The program terminates with an error"]', 0, 'snprintf writes at most size − 1 characters and always adds a zero. It returns the length the result would have had without truncation (9), so the return value tells you the text was truncated.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 2, 'Why is the loop while (!feof(f)) { fgets(…); process(…); } wrong?', '["feof works only with binary files", "fgets can''t be called in a loop", "feof is set only after a failed read: the last fgets call reads nothing, but the processing still runs", "The loop is infinite"]', 2, 'The end-of-file indicator is set after a failed read attempt. Check the result of the read function itself: while (fgets(…)).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 3, 'What does strtol("42xyz", &end, 10) give?', '["0 and an error", "42, and end points to \"xyz\"", "LONG_MAX", "Undefined behavior"]', 1, 'strtol parses the prefix that is valid as a number and reports where it stopped: *end != 0 means extra characters remain in the string.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 8, 4, 'Why does fgetc return int rather than char?', '["To run faster on 64-bit platforms", "So that the EOF marker (−1) can be told apart from the code of any real character", "Because a char can''t be returned from a function", "For compatibility with printf"]', 1, 'The result is a character code from 0 to 255, or EOF. If you store it in a char, EOF may coincide with the real character 0xFF, or may never be recognized on platforms where char is unsigned.');
